def compute(vars):
    receivables = vars["v1"]
    doubtful_allowance = vars["v2"]
    if receivables == 0:
        return None
    doubtful_percentage = -doubtful_allowance / receivables * 100
    return {
        "value": doubtful_percentage,
        "trace": {
            "receivables": receivables,
            "doubtful_allowance": doubtful_allowance,
            "doubtful_percentage": doubtful_percentage,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percentage"
            }
        }
    }
